const { Given, When, Then } = require('@cucumber/cucumber');

// ---- helpers ----------------------------------------------------------------

function todoLis(world) {
  return Array.prototype.slice.call(world.document.querySelectorAll('.todo-list li'));
}
function todoLi(world, title) {
  return todoLis(world).filter(function (li) {
    var label = li.querySelector('label');
    return label && label.textContent === title;
  })[0];
}
function storedTodos(window) {
  var raw = window.localStorage.getItem('todos-vanilla');
  if (!raw) return [];
  try { return JSON.parse(raw); } catch (e) { return []; }
}
function storedRecord(window, title) {
  return storedTodos(window).filter(function (t) { return t.title === title; })[0];
}
var seedSeq = 0;
function setStoredTodo(window, title, completed) {
  var arr = storedTodos(window);
  arr.push({ id: 'seed-' + (seedSeq++), title: title, completed: completed });
  window.localStorage.setItem('todos-vanilla', JSON.stringify(arr));
}

function addTodoViaUI(world, title) {
  var input = world.document.querySelector('.new-todo');
  input.value = title;
  var e = new world.window.KeyboardEvent('keydown', { bubbles: true, key: 'Enter' });
  input.dispatchEvent(e);
}
function checkTodoByTitle(world, title, checked) {
  var li = todoLi(world, title);
  if (!li) throw new Error('no todo with title "' + title + '"');
  var toggle = li.querySelector('.toggle');
  toggle.checked = checked;
  toggle.dispatchEvent(new world.window.Event('change', { bubbles: true }));
}
function enterEditing(world, title) {
  var li = todoLi(world, title);
  if (!li) throw new Error('no todo with title "' + title + '"');
  li.querySelector('label').dispatchEvent(new world.window.Event('dblclick', { bubbles: true }));
}
function editingInput(world) {
  return world.document.querySelector('.todo-list li.editing .edit');
}

// Capture the current <li> for a title so a later step can assert the node survived the
// interaction in place. This is verification support: it asserts nothing about production, it
// only records the node a scenario holds before the change. It carries no production plank.
Given('the list item for {string} is captured', function (title) {
  var li = todoLi(this, title);
  if (!li) throw new Error('no todo with title "' + title + '" to capture');
  this.capturedNodes = this.capturedNodes || {};
  this.capturedNodes[title] = li;
});

// Assert the node captured before the change is the same node still attached to the list after
// the change. Production MUST mutate the list item in place rather than rebuild the list, so if
// the app detached and recreated the <li> the captured reference is no longer the current node.
Then('the list item for {string} is the captured node', function (title) {
  var captured = this.capturedNodes && this.capturedNodes[title];
  if (!captured) throw new Error('no captured node for "' + title + '"');
  var current = todoLi(this, title);
  if (!current) throw new Error('todo "' + title + '" is no longer in the list after the change');
  if (captured !== current)
    throw new Error('list item for "' + title + '" was rebuilt, not mutated in place');
  if (!captured.parentNode || !captured.parentNode.classList.contains('todo-list'))
    throw new Error('captured list item for "' + title + '" is no longer attached to the todo list');
});

// ---- given: starting state --------------------------------------------------

Given('the app has no todos', function () {
  var n = todoLis(this).length;
  if (n !== 0) throw new Error('expected no todos, found ' + n);
});

Given('the app has the todo {string}', function (title) {
  addTodoViaUI(this, title);
});
Given('the app has the active todo {string}', function (title) {
  addTodoViaUI(this, title);
});
Given('the app has the completed todo {string}', function (title) {
  addTodoViaUI(this, title);
  checkTodoByTitle(this, title, true);
});
Given('the app has {int} active todos', function (count) {
  for (var i = 1; i <= count; i++) addTodoViaUI(this, 'Active todo ' + i);
});

// Direct localStorage setup: seed the persisted record without going through the UI.
// These are preconditions for reload/persistence scenarios, so they use verification support
// alone and carry no production plank.
Given('localStorage holds the todo {string}', function (title) {
  setStoredTodo(this.window, title, false);
});
Given('localStorage holds the completed todo {string}', function (title) {
  setStoredTodo(this.window, title, true);
});
Given('localStorage holds the active todo {string}', function (title) {
  setStoredTodo(this.window, title, false);
});

// The same phrase is both a precondition (enter editing) and an assertion (verify editing)
// in the specs, so cucumber-js needs a single definition: ensure editing, then assert.
Given('the todo {string} is in editing mode', function (title) {
  var li = todoLi(this, title);
  if (!li) throw new Error('no todo with title "' + title + '"');
  if (!li.classList.contains('editing')) enterEditing(this, title);
  if (!li.classList.contains('editing'))
    throw new Error('"' + title + '" could not be put into editing mode');
});

// ---- when: actions ----------------------------------------------------------

When('the user types {string} into the new todo input and presses Enter', function (text) {
  var input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { bubbles: true, key: 'Enter' }));
});

When('the user checks the todo {string}', function (title) {
  checkTodoByTitle(this, title, true);
});
When('the user unchecks the todo {string}', function (title) {
  checkTodoByTitle(this, title, false);
});

When('the user checks the mark all as complete checkbox', function () {
  var t = this.document.querySelector('#toggle-all');
  t.checked = true;
  t.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});
When('the user unchecks the mark all as complete checkbox', function () {
  var t = this.document.querySelector('#toggle-all');
  t.checked = false;
  t.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('the user clicks clear completed', function () {
  this.document.querySelector('.clear-completed')
    .dispatchEvent(new this.window.Event('click', { bubbles: true }));
});

When('the user double-clicks the label of the todo {string}', function (title) {
  var li = todoLi(this, title);
  if (!li) throw new Error('no todo with title "' + title + '"');
  li.querySelector('label').dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
});

When('the user changes the edit input to {string} and presses Enter', function (value) {
  var edit = editingInput(this);
  if (!edit) throw new Error('no todo in editing mode');
  edit.value = value;
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { bubbles: true, key: 'Enter' }));
});
When('the user changes the edit input to {string} and blurs the input', function (value) {
  var edit = editingInput(this);
  if (!edit) throw new Error('no todo in editing mode');
  edit.value = value;
  edit.dispatchEvent(new this.window.Event('blur'));
});
When('the user changes the edit input to {string} and presses Escape', function (value) {
  var edit = editingInput(this);
  if (!edit) throw new Error('no todo in editing mode');
  edit.value = value;
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { bubbles: true, key: 'Escape' }));
});

When('the user navigates to {string}', function (hash) {
  this.navigate(hash);
});

When('the app is reloaded', function () {
  var snapshot = {};
  var ls = this.window.localStorage;
  for (var i = 0; i < ls.length; i++) {
    var k = ls.key(i);
    snapshot[k] = ls.getItem(k);
  }
  this.loadApp(snapshot);
});

// ---- then: assertions -------------------------------------------------------

Then('the main section is not visible', function () {
  if (!this.document.querySelector('.main').hidden) throw new Error('main section is visible');
});
Then('the footer section is not visible', function () {
  if (!this.document.querySelector('.footer').hidden) throw new Error('footer section is visible');
});

Then('the todo list shows the todo {string}', function (title) {
  if (!todoLi(this, title)) throw new Error('todo list does not show "' + title + '"');
});
Then('the todo list shows the todos {string} and {string}', function (a, b) {
  if (!todoLi(this, a)) throw new Error('todo list does not show "' + a + '"');
  if (!todoLi(this, b)) throw new Error('todo list does not show "' + b + '"');
});
Then('the todo list shows only the todo {string}', function (title) {
  var lis = todoLis(this);
  if (lis.length !== 1) throw new Error('expected exactly 1 todo, found ' + lis.length);
  if (lis[0].querySelector('label').textContent !== title)
    throw new Error('only todo is not "' + title + '"');
});
Then('the todo list is empty', function () {
  var n = todoLis(this).length;
  if (n !== 0) throw new Error('expected empty todo list, found ' + n);
});

Then('the new todo input is empty', function () {
  if (this.document.querySelector('.new-todo').value !== '')
    throw new Error('new todo input is not empty');
});
Then('the new todo input is focused', function () {
  if (this.document.activeElement !== this.document.querySelector('.new-todo'))
    throw new Error('new todo input is not focused');
});

Then('the todo {string} is marked completed', function (title) {
  var li = todoLi(this, title);
  if (!li) throw new Error('no todo with title "' + title + '"');
  if (!li.classList.contains('completed')) throw new Error('"' + title + '" is not marked completed');
});
Then('the todo {string} is not marked completed', function (title) {
  var li = todoLi(this, title);
  if (!li) throw new Error('no todo with title "' + title + '"');
  if (li.classList.contains('completed')) throw new Error('"' + title + '" is marked completed');
});
Then('every todo is marked completed', function () {
  var lis = todoLis(this);
  if (lis.length === 0) throw new Error('no todos');
  if (!lis.every(function (li) { return li.classList.contains('completed'); }))
    throw new Error('some todos are not completed');
});
Then('every todo is not marked completed', function () {
  var lis = todoLis(this);
  if (lis.length === 0) throw new Error('no todos');
  if (!lis.every(function (li) { return !li.classList.contains('completed'); }))
    throw new Error('some todos are completed');
});
Then('the mark all as complete checkbox is checked', function () {
  if (!this.document.querySelector('#toggle-all').checked)
    throw new Error('mark all checkbox is not checked');
});
Then('the mark all as complete checkbox is unchecked', function () {
  if (this.document.querySelector('#toggle-all').checked)
    throw new Error('mark all checkbox is checked');
});

Then("the counter's strong element contains {string}", function (text) {
  var strong = this.document.querySelector('.todo-count strong');
  if (!strong) throw new Error('counter has no strong element');
  if (strong.textContent.trim() !== text)
    throw new Error('counter strong is "' + strong.textContent.trim() + '", expected "' + text + '"');
});
Then('the counter shows {string}', function (text) {
  var actual = this.document.querySelector('.todo-count').textContent.replace(/\s+/g, ' ').trim();
  if (actual.indexOf(text) === -1)
    throw new Error('counter "' + actual + '" does not include "' + text + '"');
});

Then('the clear completed button is not visible', function () {
  if (!this.document.querySelector('.clear-completed').hidden)
    throw new Error('clear completed button is visible');
});
Then('the clear completed button is visible', function () {
  if (this.document.querySelector('.clear-completed').hidden)
    throw new Error('clear completed button is not visible');
});

Then('the todo {string} is not in editing mode', function (title) {
  var li = todoLi(this, title);
  if (li && li.classList.contains('editing'))
    throw new Error('"' + title + '" is in editing mode');
});

Then('localStorage holds a todo record for {string}', function (title) {
  if (!storedRecord(this.window, title))
    throw new Error('localStorage holds no record for "' + title + '"');
});
Then('localStorage has the key {string}', function (key) {
  if (this.window.localStorage.getItem(key) === null)
    throw new Error('localStorage has no key "' + key + '"');
});
Then(/^the persisted record for "(.*)" has the keys (.*)$/, function (title, keysStr) {
  var rec = storedRecord(this.window, title);
  if (!rec) throw new Error('localStorage holds no record for "' + title + '"');
  var keys = keysStr.split(/\s+and\s+|\s*,\s*/)
    .map(function (s) { return s.replace(/^"|"$/g, '').trim(); })
    .filter(Boolean);
  keys.forEach(function (k) {
    if (!(k in rec)) throw new Error('record for "' + title + '" missing key "' + k +
      '"; has ' + Object.keys(rec).join(', '));
  });
});
Then(/^the persisted record for "(.*)" has "(.*)" equal to (.*)$/, function (title, key, value) {
  var rec = storedRecord(this.window, title);
  if (!rec) throw new Error('localStorage holds no record for "' + title + '"');
  var actual = rec[key];
  var want;
  if (value === 'true') want = true;
  else if (value === 'false') want = false;
  else if (/^".*"$/.test(value)) want = value.slice(1, -1);
  else want = value;
  if (actual !== want)
    throw new Error('record.' + key + ' = ' + JSON.stringify(actual) + ', expected ' + JSON.stringify(want));
});

Then('the {string} filter link is selected', function (name) {
  var link = Array.prototype.slice.call(this.document.querySelectorAll('.filters a'))
    .filter(function (a) { return a.textContent.trim() === name; })[0];
  if (!link) throw new Error('no filter link "' + name + '"');
  if (!link.classList.contains('selected')) throw new Error('"' + name + '" filter link is not selected');
});

// ---- conformance: empty-edit removal safety ---------------------------------
// A @conformance scenario that scans js/app.js for an unguarded removeChild on a stale list
// item. An empty edit commits its removal through both the edit blur handler and the keydown
// handler, so render may run twice over the same change; a stale item an earlier render already
// detached must never reach a removeChild that throws NotFoundError. This is a bespoke
// conformance checker: no independent tool expresses the constraint, and it asserts real source
// structure, so it is verification support under QM, not a test double.

const fs = require('node:fs');
const path = require('node:path');

function sourceAt(rel) {
  const p = path.resolve(__dirname, '..', '..', rel);
  if (!fs.existsSync(p)) throw new Error('conformance: source not found at "' + rel + '"');
  return fs.readFileSync(p, 'utf8');
}

// Every `if (cond) { ... }` / `if (cond) stmt;` in the source, with the condition text and the
// body range (so a call inside the body is "guarded" by that if). Bodies may be braced `{...}`
// or a single following statement terminated by `;`.
function ifBodies(src) {
  const bodies = [];
  const re = /(?:^|[^.\w])if\s*\(/g;
  let m;
  while ((m = re.exec(src)) !== null) {
    const parenAt = m.index + m[0].length - 1; // index of '('
    let depth = 0, condEnd = -1;
    for (let i = parenAt; i < src.length; i++) {
      if (src[i] === '(') depth++;
      else if (src[i] === ')') { depth--; if (depth === 0) { condEnd = i; break; } }
    }
    if (condEnd === -1) continue;
    const cond = src.slice(parenAt + 1, condEnd);
    let j = condEnd + 1;
    while (j < src.length && /\s/.test(src[j])) j++;
    let bodyStart, bodyEnd;
    if (src[j] === '{') {
      let bdepth = 0;
      bodyStart = j + 1;
      for (let k = j; k < src.length; k++) {
        if (src[k] === '{') bdepth++;
        else if (src[k] === '}') { bdepth--; if (bdepth === 0) { bodyEnd = k; break; } }
      }
    } else {
      let k = j;
      while (k < src.length && src[k] !== ';') k++;
      bodyStart = j; bodyEnd = k;
    }
    bodies.push({ cond, bodyStart, bodyEnd });
  }
  return bodies;
}

// A real connectivity guard tests that the node is actually still part of its parent: `isConnected`
// or `parent.contains(node)`. A bare `parentNode` truthiness read is NOT a connectivity test — in a
// re-entrant render the stale node's `parentNode` can stay truthy while the node is no longer that
// parent's child, so `if (node.parentNode) parent.removeChild(node)` still throws NotFoundError.
function isConnectivityGuard(cond) {
  return /\bisConnected\b/.test(cond) || /\bcontains\s*\(/.test(cond);
}

// Find removeChild calls on a list item (the `X.parentNode.removeChild(...)` form) that are not
// behind a real connectivity guard. `node.remove()` is inherently safe (a no-op when detached), so
// only the removeChild form is scrutinised here. Such a call would throw on an already-detached
// node in a real browser when render runs twice over the same edit-commit change.
function unguardedRemovalCalls(src) {
  const bodies = ifBodies(src);
  const unguarded = [];
  const re = /\.removeChild\s*\(/g;
  let m;
  while ((m = re.exec(src)) !== null) {
    const callAt = m.index;
    const guarded = bodies.some(
      (b) => isConnectivityGuard(b.cond) && callAt >= b.bodyStart && callAt <= b.bodyEnd
    );
    if (!guarded) unguarded.push(callAt);
  }
  return unguarded;
}

Given('the app source at {string}', function (rel) {
  this.conformanceSource = sourceAt(rel);
});

When('the verifier checks the edit-commit removal path', function () {
  if (!this.conformanceSource) throw new Error('conformance: no source loaded; run the "the app source at" step first');
  this.unguardedRemovals = unguardedRemovalCalls(this.conformanceSource);
});

Then('no removeChild is issued on a list item without a connectivity guard', function () {
  const bad = this.unguardedRemovals || [];
  if (bad.length > 0)
    throw new Error('found ' + bad.length + ' unguarded removeChild call(s) on a list item: a stale, already-detached node would reach a throwing removeChild');
});

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  //
  // localStorage snapshot: happy-dom gives each Window its own Storage, so a fresh Window on
  // reload would lose persisted todos and the persisted route. A real browser keeps
  // localStorage across a reload, so when a scenario reloads the app we snapshot the current
  // Storage and restore it into the new Window BEFORE the app's init reads it. This models
  // real reload semantics (fresh DOM and JS, durable localStorage) without faking the app.
  loadApp(localStorageSnapshot) {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    // disableCSSFileLoading: the template links CSS from node_modules via http://localhost/, which
    // would otherwise attempt a network fetch; the executable tier asserts structure and classes,
    // never computed styles, so CSS need not load.
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true, disableCSSFileLoading: true },
    });
    this.document = this.window.document;

    if (localStorageSnapshot) {
      for (const key of Object.keys(localStorageSnapshot)) {
        this.window.localStorage.setItem(key, localStorageSnapshot[key]);
      }
    }

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

/**
 * TodoMVC (vanilla JS). The executable tier drives this through the real DOM that
 * features/support/world.js loads; no build step, no framework. Behaviour is split into
 * small seams, each carrying @planks(...) that name the Gherkin step patterns it serves.
 */
(function () {
  'use strict';

  const STORAGE_KEY = 'todos-vanilla';
  const FILTER_KEY = 'todos-vanilla-filter';
  const ENTER_KEY = 13;
  const ESCAPE_KEY = 27;

  var todos = [];
  var filter = 'all';

  function $(sel) { return document.querySelector(sel); }
  function $all(sel) { return Array.prototype.slice.call(document.querySelectorAll(sel)); }

  function genId() {
    return 't' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  /**
   * Read todos and the persisted active filter from localStorage.
   * @planks("the app is reloaded")
   */
  function load() {
    todos = [];
    filter = 'all';
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (raw) todos = JSON.parse(raw);
    } catch (e) {
      todos = [];
    }
    if (!Array.isArray(todos)) todos = [];
    var f = localStorage.getItem(FILTER_KEY);
    if (f === 'active' || f === 'completed' || f === 'all') filter = f;
  }

  /**
   * Persist todos and the active filter, and shape the durable localStorage record.
   * @planks("localStorage holds a todo record for {string}")
   * @planks("localStorage has the key {string}")
   * @planks("^the persisted record for \"(.*)\" has the keys (.*)$")
   * @planks("^the persisted record for \"(.*)\" has \"(.*)\" equal to (.*)$")
   */
  function save() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    localStorage.setItem(FILTER_KEY, filter);
  }

  // Persist only the active filter. Navigation must not rewrite the todo list: a scenario can
  // seed localStorage directly (a precondition) and then reload, and a full save() would clobber
  // the seeded todos with the app's in-memory list.
  function saveFilter() {
    localStorage.setItem(FILTER_KEY, filter);
  }

  function parseRoute(hash) {
